@keyframes hero-rise-30 { from { opacity: 0; transform: translateY(30px); } }
@keyframes hero-rise-20 { from { opacity: 0; transform: translateY(20px); } }
@keyframes hero-grow { from { opacity: 0; transform: scale(0.95); } }
