/* ═══════════════════════════════════════════════
   VORTEX RADAR CYCLONE DEFAULTS & EXACT RADAR CANVAS
   ═══════════════════════════════════════════════ */

const DEFAULT_VORTEX_METRICS = [
  { value: "134M", label: "PARCELS COVERED" },
  { value: "412K", label: "SCORES A DAY" },
  { value: "180ms", label: "P95 RESPONSE" },
